def cstr(addr, limit=200):
    if not addr or addr <= 0 or addr >= len(data):
        return None
    end = data.find(bytes([0]), addr, addr + limit)
    return data[addr:end].decode("latin1") if end > 0 else None

def show(addr):
    q = struct.unpack_from("<QQQQ", data, addr)
    isa = fixmap.get(addr, q[0])
    flags = q[1]
    ptr = fixmap.get(addr + 0x10, q[2])
    length = q[3]
